package org.springframework.samples.petclinic.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: every owner is identified by a single derived {@code identityKey} of
 * {@code normalizedTelephone|email|householdId}. This consolidates the former separate
 * telephone, email and household duplicate checks into one key: on creation an owner is
 * rejected only when its WHOLE identityKey exactly matches an existing owner's. Because the
 * telephone is part of the key, two members of the same household (same householdId) with
 * different telephones have different identityKeys and are both allowed; only an exact
 * full-key match is a duplicate. Kept as a small, self-contained unit so the rule can be
 * enforced from the create flow without adding complexity to the controller or service.
 */
public final class OwnerIdentityPolicy {

    private OwnerIdentityPolicy() {
    }

    /**
     * Assign the owner's householdId (when it knowingly joins an existing household) and reject
     * the owner when its whole identityKey matches any other existing owner's.
     *
     * @param clinicService   source of the existing owners
     * @param owner           the owner being created
     * @param sharesHousehold whether the request opted in to a shared household
     * @throws DuplicateIdentityException if the identityKey is already in use
     */
    public static void rejectDuplicateIdentity(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
        assignHouseholdId(clinicService, owner, sharesHousehold);
        String key = identityKey(owner);
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId()) && key.equals(identityKey(existing))) {
                throw new DuplicateIdentityException();
            }
        }
    }

    /** The owner's derived identity key: normalized telephone, email and household id, '|'-joined. */
    public static String identityKey(Owner owner) {
        return normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail()) + "|"
            + orEmpty(owner.getHouseholdId());
    }

    /** Adopt the existing household's id when sharing was opted in and a matching owner already exists. */
    private static void assignHouseholdId(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
        if (!Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        String lastName = normalizeHousehold(owner.getLastName());
        String address = normalizeHousehold(owner.getAddress());
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId())
                && lastName.equals(normalizeHousehold(existing.getLastName()))
                && address.equals(normalizeHousehold(existing.getAddress()))) {
                owner.setHouseholdId(householdId(lastName, address));
                return;
            }
        }
    }

    private static String normalizeTelephone(String telephone) {
        return telephone == null ? "" : telephone.replaceAll("\\D", "");
    }

    private static String normalizeEmail(String email) {
        return email == null ? "" : email.toLowerCase();
    }

    private static String normalizeHousehold(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }

    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
    private static String householdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Thrown when another owner already has the same identityKey. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateIdentityException extends RuntimeException {
    }
}
package org.springframework.samples.petclinic.service;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: an owner that is not a hard duplicate but shares an existing owner's last name
 * and postcode with a different telephone is still created and flagged as a possible duplicate.
 * On creation the owner records {@code possibleDuplicateOf} (the matching owner's id), from which
 * {@code possibleDuplicate} is derived; when nothing matches it stays absent. Kept as a small,
 * self-contained unit so the rule can be applied from the create flow without adding complexity
 * to the controller or service.
 */
public final class OwnerPossibleDuplicatePolicy {

    private OwnerPossibleDuplicatePolicy() {
    }

    /**
     * Record {@code possibleDuplicateOf} for a newly created owner when another owner shares its
     * last name and postcode but has a different telephone.
     *
     * @param clinicService source of the existing owners
     * @param owner         the owner being created
     */
    public static void assignPossibleDuplicate(ClinicService clinicService, Owner owner) {
        String postcode = orEmpty(owner.getPostcode());
        if (postcode.isEmpty()) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String telephone = normalizeTelephone(owner.getTelephone());
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId())
                && lastName.equals(normalize(existing.getLastName()))
                && postcode.equals(orEmpty(existing.getPostcode()))
                && !telephone.equals(normalizeTelephone(existing.getTelephone()))) {
                owner.setPossibleDuplicateOf(existing.getId());
                return;
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String normalizeTelephone(String telephone) {
        return telephone == null ? "" : telephone.replaceAll("\\D", "");
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}
package org.springframework.samples.petclinic.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: a household is keyed on (last name, postcode). Every owner is given a
 * deterministic {@code householdId} on creation &mdash; the first 12 hex characters of
 * SHA-256 over {@code normalizedLastName|postcode} &mdash; so owners with the same last name
 * and postcode share it automatically. Because they are the same household, a second such owner
 * is rejected unless the request opts in to sharing ({@code sharesHousehold == true}), which only
 * bypasses the rejection; the id is assigned either way. Kept as a small, self-contained unit so
 * the rule can be enforced from the create flow without adding complexity to the controller or
 * service.
 */
public final class OwnerHouseholdPolicy {

    private OwnerHouseholdPolicy() {
    }

    /**
     * Assign the owner's deterministic {@code householdId} and reject it when another existing owner
     * is in the same (last name, postcode) household, unless the request opted in to sharing.
     *
     * @param clinicService   source of the existing owners
     * @param owner           the owner being created
     * @param sharesHousehold whether the request opted in to a shared household
     * @throws DuplicateHouseholdException if the household already exists and sharing was not opted in
     */
    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
        String lastName = normalize(owner.getLastName());
        String postcode = orEmpty(owner.getPostcode());
        owner.setHouseholdId(householdId(lastName, postcode));
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId())
                && lastName.equals(normalize(existing.getLastName()))
                && postcode.equals(orEmpty(existing.getPostcode()))) {
                if (!Boolean.TRUE.equals(sharesHousehold)) {
                    throw new DuplicateHouseholdException();
                }
                return;
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }

    /** Derive a stable identifier shared by every owner in the same (last name, postcode) household. */
    private static String householdId(String lastName, String postcode) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Thrown when another owner already shares the same last name and postcode. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateHouseholdException extends RuntimeException {
    }
}

